// archicad-guard: what a Tapir command does to the project (point 1.2). The lists live in ./commands.ts, generated by
// scripts/build-command-map.py; this file only looks a name up. Fail closed: anything not listed is a change.

import { CHANGE_COMMANDS, DRY_RUN_COMMANDS, READ_COMMANDS, VIEW_COMMANDS } from './commands'

/**
 * - `read`: returns data, changes nothing. Passes.
 * - `view`: changes only Archicad's screen or selection (zoom, window, select, highlight, alert). Passes, not logged.
 * - `change`: changes the model, the project's settings or files on disk, or is unknown. Asks.
 */
export type CommandKind = 'read' | 'view' | 'change'

const KINDS: ReadonlyMap<string, CommandKind> = new Map<string, CommandKind>([
  ...READ_COMMANDS.map(name => [name, 'read'] as const),
  ...VIEW_COMMANDS.map(name => [name, 'view'] as const),
  ...CHANGE_COMMANDS.map(name => [name, 'change'] as const),
])

const DRY_RUN: ReadonlySet<string> = new Set(DRY_RUN_COMMANDS)

/** The kind of a Tapir command, by its exact name. A missing, non-string or unknown name is a change. */
export const kindOf = (name: unknown): CommandKind => (typeof name === 'string' ? KINDS.get(name) : undefined) ?? 'change'

/** Whether the command takes `dryRun: true` to preview what it would do. */
export const takesDryRun = (name: unknown): boolean => typeof name === 'string' && DRY_RUN.has(name)

/** Whether the name is in the command map at all (an unknown one is still treated as a change). */
export const isKnownCommand = (name: unknown): boolean => typeof name === 'string' && KINDS.has(name)
